insert into public.species (id, slug, name, height_decimeters, weight_hectograms, description, gender_rate, base_hp, base_attack, base_defense, base_special_attack, base_special_defense, base_speed, ev_yield_hp, ev_yield_attack, ev_yield_defense, ev_yield_special_attack, ev_yield_special_defense, ev_yield_speed) values
  (1, 'bulbasaur', 'Bulbasaur', 7, 69, 'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.', 1, 45, 49, 49, 65, 65, 45, 0, 0, 0, 1, 0, 0),
  (2, 'ivysaur', 'Ivysaur', 10, 130, 'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.', 1, 60, 62, 63, 80, 80, 60, 0, 0, 0, 1, 1, 0),
  (3, 'venusaur', 'Venusaur', 20, 1000, 'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.', 1, 80, 82, 83, 100, 100, 80, 0, 0, 0, 2, 1, 0),
  (4, 'charmander', 'Charmander', 6, 85, 'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.', 1, 39, 52, 43, 60, 50, 65, 0, 0, 0, 0, 0, 1),
  (5, 'charmeleon', 'Charmeleon', 11, 190, 'When it swings its burning tail, it elevates the temperature to unbearably high levels.', 1, 58, 64, 58, 80, 65, 80, 0, 0, 0, 1, 0, 1),
  (6, 'charizard', 'Charizard', 17, 905, 'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.', 1, 78, 84, 78, 109, 85, 100, 0, 0, 0, 3, 0, 0),
  (7, 'squirtle', 'Squirtle', 5, 90, 'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.', 1, 44, 48, 65, 50, 64, 43, 0, 0, 1, 0, 0, 0),
  (8, 'wartortle', 'Wartortle', 10, 225, 'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.', 1, 59, 63, 80, 65, 80, 58, 0, 0, 1, 0, 1, 0),
  (9, 'blastoise', 'Blastoise', 16, 855, 'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.', 1, 79, 83, 100, 85, 105, 78, 0, 0, 0, 0, 3, 0),
  (10, 'caterpie', 'Caterpie', 3, 29, 'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.', 4, 45, 30, 35, 20, 20, 45, 1, 0, 0, 0, 0, 0),
  (11, 'metapod', 'Metapod', 7, 99, 'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.', 4, 50, 20, 55, 25, 25, 30, 0, 0, 2, 0, 0, 0),
  (12, 'butterfree', 'Butterfree', 11, 320, 'In battle, it flaps its wings at high speed to release highly toxic dust into the air.', 4, 60, 45, 50, 90, 80, 70, 0, 0, 0, 2, 1, 0),
  (13, 'weedle', 'Weedle', 3, 32, 'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.', 4, 40, 35, 30, 20, 20, 50, 0, 0, 0, 0, 0, 1),
  (14, 'kakuna', 'Kakuna', 6, 100, 'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.', 4, 45, 25, 50, 25, 25, 35, 0, 0, 2, 0, 0, 0),
  (15, 'beedrill', 'Beedrill', 10, 295, 'Flies at high speed and attacks using its large venomous stingers on its forelegs and tail.', 4, 65, 90, 40, 45, 80, 75, 0, 2, 0, 0, 1, 0),
  (16, 'pidgey', 'Pidgey', 3, 18, 'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.', 4, 40, 45, 40, 35, 35, 56, 0, 0, 0, 0, 0, 1),
  (17, 'pidgeotto', 'Pidgeotto', 11, 300, 'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.', 4, 63, 60, 55, 50, 50, 71, 0, 0, 0, 0, 0, 2),
  (18, 'pidgeot', 'Pidgeot', 15, 395, 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.', 4, 83, 80, 75, 70, 70, 101, 0, 0, 0, 0, 0, 3),
  (19, 'rattata', 'Rattata', 3, 35, 'Bites anything when it attacks. Small and very quick, it is a common sight in many places.', 4, 30, 56, 35, 25, 35, 72, 0, 0, 0, 0, 0, 1),
  (20, 'raticate', 'Raticate', 7, 185, 'It uses its whiskers to maintain its balance. It apparently slows down if they are cut off.', 4, 55, 81, 60, 50, 70, 97, 0, 0, 0, 0, 0, 2),
  (21, 'spearow', 'Spearow', 3, 20, 'Eats bugs in grassy areas. It has to flap its short wings at high speed to stay airborne.', 4, 40, 60, 30, 31, 31, 70, 0, 0, 0, 0, 0, 1),
  (22, 'fearow', 'Fearow', 12, 380, 'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.', 4, 65, 90, 65, 61, 61, 100, 0, 0, 0, 0, 0, 2),
  (23, 'ekans', 'Ekans', 20, 69, 'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.', 4, 35, 60, 44, 40, 54, 55, 0, 1, 0, 0, 0, 0),
  (24, 'arbok', 'Arbok', 35, 650, 'It is rumored that the ferocious warning markings on its belly differ from area to area.', 4, 60, 95, 69, 65, 79, 80, 0, 2, 0, 0, 0, 0),
  (25, 'pikachu', 'Pikachu', 4, 60, 'When several of these POKéMON gather, their electricity could build and cause lightning storms.', 4, 35, 55, 40, 50, 50, 90, 0, 0, 0, 0, 0, 2),
  (26, 'raichu', 'Raichu', 8, 300, 'Its long tail serves as a ground to protect itself from its own high voltage power.', 4, 60, 90, 55, 90, 80, 110, 0, 0, 0, 0, 0, 3),
  (27, 'sandshrew', 'Sandshrew', 6, 120, 'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.', 4, 50, 75, 85, 20, 30, 40, 0, 0, 1, 0, 0, 0),
  (28, 'sandslash', 'Sandslash', 10, 295, 'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.', 4, 75, 100, 110, 45, 55, 65, 0, 0, 2, 0, 0, 0),
  (29, 'nidoran-f', 'Nidoran♀ (female)', 4, 70, 'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.', 8, 55, 47, 52, 40, 40, 41, 1, 0, 0, 0, 0, 0),
  (30, 'nidorina', 'Nidorina', 8, 200, 'The female’s horn develops slowly. Prefers physical attacks such as clawing and biting.', 8, 70, 62, 67, 55, 55, 56, 2, 0, 0, 0, 0, 0),
  (31, 'nidoqueen', 'Nidoqueen', 13, 600, 'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.', 8, 90, 92, 87, 75, 85, 76, 3, 0, 0, 0, 0, 0),
  (32, 'nidoran-m', 'Nidoran♂ (male)', 5, 90, 'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.', 0, 46, 57, 40, 40, 40, 50, 0, 1, 0, 0, 0, 0),
  (33, 'nidorino', 'Nidorino', 9, 195, 'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.', 0, 61, 72, 57, 55, 55, 65, 0, 2, 0, 0, 0, 0),
  (34, 'nidoking', 'Nidoking', 14, 620, 'It uses its powerful tail in battle to smash, constrict, then break the prey’s bones.', 0, 81, 102, 77, 85, 75, 85, 0, 3, 0, 0, 0, 0),
  (35, 'clefairy', 'Clefairy', 6, 75, 'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.', 6, 70, 45, 48, 60, 65, 35, 2, 0, 0, 0, 0, 0),
  (36, 'clefable', 'Clefable', 13, 400, 'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.', 6, 95, 70, 73, 95, 90, 60, 3, 0, 0, 0, 0, 0),
  (37, 'vulpix', 'Vulpix', 6, 99, 'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.', 6, 38, 41, 40, 50, 65, 65, 0, 0, 0, 0, 0, 1),
  (38, 'ninetales', 'Ninetales', 11, 199, 'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.', 6, 73, 76, 75, 81, 100, 100, 0, 0, 0, 0, 1, 1),
  (39, 'jigglypuff', 'Jigglypuff', 5, 55, 'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.', 6, 115, 45, 20, 45, 25, 20, 2, 0, 0, 0, 0, 0),
  (40, 'wigglytuff', 'Wigglytuff', 10, 120, 'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.', 6, 140, 70, 45, 85, 50, 45, 3, 0, 0, 0, 0, 0),
  (41, 'zubat', 'Zubat', 8, 75, 'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.', 4, 40, 45, 35, 30, 40, 55, 0, 0, 0, 0, 0, 1),
  (42, 'golbat', 'Golbat', 16, 550, 'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.', 4, 75, 80, 70, 65, 75, 90, 0, 0, 0, 0, 0, 2),
  (43, 'oddish', 'Oddish', 5, 54, 'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.', 4, 45, 50, 55, 75, 65, 30, 0, 0, 0, 1, 0, 0),
  (44, 'gloom', 'Gloom', 8, 86, 'The fluid that oozes from its mouth isn’t drool. It is a nectar that is used to attract prey.', 4, 60, 65, 70, 85, 75, 40, 0, 0, 0, 2, 0, 0),
  (45, 'vileplume', 'Vileplume', 12, 186, 'The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.', 4, 75, 80, 85, 110, 90, 50, 0, 0, 0, 3, 0, 0),
  (46, 'paras', 'Paras', 3, 54, 'Burrows to suck tree roots. The mushrooms on its back grow by drawing nutrients from the bug host.', 4, 35, 70, 55, 45, 55, 25, 0, 1, 0, 0, 0, 0),
  (47, 'parasect', 'Parasect', 10, 295, 'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.', 4, 60, 95, 80, 60, 80, 30, 0, 2, 1, 0, 0, 0),
  (48, 'venonat', 'Venonat', 10, 300, 'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.', 4, 60, 55, 50, 40, 55, 45, 0, 0, 0, 0, 1, 0),
  (49, 'venomoth', 'Venomoth', 15, 125, 'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.', 4, 70, 65, 60, 90, 75, 90, 0, 0, 0, 1, 0, 1),
  (50, 'diglett', 'Diglett', 2, 8, 'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.', 4, 10, 55, 25, 35, 45, 95, 0, 0, 0, 0, 0, 1),
  (51, 'dugtrio', 'Dugtrio', 7, 333, 'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.', 4, 35, 100, 50, 50, 70, 120, 0, 0, 0, 0, 0, 2),
  (52, 'meowth', 'Meowth', 4, 42, 'Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.', 4, 40, 45, 35, 40, 40, 90, 0, 0, 0, 0, 0, 1),
  (53, 'persian', 'Persian', 10, 320, 'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.', 4, 65, 70, 60, 65, 65, 115, 0, 0, 0, 0, 0, 2),
  (54, 'psyduck', 'Psyduck', 8, 196, 'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.', 4, 50, 52, 48, 65, 50, 55, 0, 0, 0, 1, 0, 0),
  (55, 'golduck', 'Golduck', 17, 766, 'Often seen swimming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.', 4, 80, 82, 78, 95, 80, 85, 0, 0, 0, 2, 0, 0),
  (56, 'mankey', 'Mankey', 5, 280, 'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.', 4, 40, 80, 35, 35, 45, 70, 0, 1, 0, 0, 0, 0),
  (57, 'primeape', 'Primeape', 10, 320, 'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.', 4, 65, 105, 60, 60, 70, 95, 0, 2, 0, 0, 0, 0),
  (58, 'growlithe', 'Growlithe', 7, 190, 'Very protective of its territory. It will bark and bite to repel intruders from its space.', 2, 55, 70, 45, 70, 50, 60, 0, 1, 0, 0, 0, 0),
  (59, 'arcanine', 'Arcanine', 19, 1550, 'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.', 2, 90, 110, 80, 100, 80, 95, 0, 2, 0, 0, 0, 0),
  (60, 'poliwag', 'Poliwag', 6, 124, 'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.', 4, 40, 50, 40, 40, 40, 90, 0, 0, 0, 0, 0, 1),
  (61, 'poliwhirl', 'Poliwhirl', 10, 200, 'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.', 4, 65, 65, 65, 50, 50, 90, 0, 0, 0, 0, 0, 2),
  (62, 'poliwrath', 'Poliwrath', 13, 540, 'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.', 4, 90, 95, 95, 70, 90, 70, 0, 0, 3, 0, 0, 0),
  (63, 'abra', 'Abra', 9, 195, 'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.', 2, 25, 20, 15, 105, 55, 90, 0, 0, 0, 1, 0, 0),
  (64, 'kadabra', 'Kadabra', 13, 565, 'It emits special alpha waves from its body that induce headaches just by being close by.', 2, 40, 35, 30, 120, 70, 105, 0, 0, 0, 2, 0, 0),
  (65, 'alakazam', 'Alakazam', 15, 480, 'Its brain can outperform a supercomputer. Its intelligence quotient is said to be 5,000.', 2, 55, 50, 45, 135, 95, 120, 0, 0, 0, 3, 0, 0),
  (66, 'machop', 'Machop', 8, 195, 'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.', 2, 70, 80, 50, 35, 35, 35, 0, 1, 0, 0, 0, 0),
  (67, 'machoke', 'Machoke', 15, 705, 'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.', 2, 80, 100, 70, 50, 60, 45, 0, 2, 0, 0, 0, 0),
  (68, 'machamp', 'Machamp', 16, 1300, 'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.', 2, 90, 130, 80, 65, 85, 55, 0, 3, 0, 0, 0, 0),
  (69, 'bellsprout', 'Bellsprout', 7, 40, 'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.', 4, 50, 75, 35, 70, 30, 40, 0, 1, 0, 0, 0, 0),
  (70, 'weepinbell', 'Weepinbell', 10, 64, 'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.', 4, 65, 90, 50, 85, 45, 55, 0, 2, 0, 0, 0, 0),
  (71, 'victreebel', 'Victreebel', 17, 155, 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.', 4, 80, 105, 65, 100, 70, 70, 0, 3, 0, 0, 0, 0),
  (72, 'tentacool', 'Tentacool', 9, 455, 'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.', 4, 40, 40, 35, 50, 100, 70, 0, 0, 0, 0, 1, 0),
  (73, 'tentacruel', 'Tentacruel', 16, 550, 'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.', 4, 80, 70, 65, 80, 120, 100, 0, 0, 0, 0, 2, 0),
  (74, 'geodude', 'Geodude', 4, 200, 'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.', 4, 40, 80, 100, 30, 30, 20, 0, 0, 1, 0, 0, 0),
  (75, 'graveler', 'Graveler', 10, 1050, 'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.', 4, 55, 95, 115, 45, 45, 35, 0, 0, 2, 0, 0, 0),
  (76, 'golem', 'Golem', 14, 3000, 'Its boulder-like body is extremely hard. It can easily withstand dynamite blasts without damage.', 4, 80, 120, 130, 55, 65, 45, 0, 0, 3, 0, 0, 0),
  (77, 'ponyta', 'Ponyta', 10, 300, 'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.', 4, 50, 85, 55, 65, 65, 90, 0, 0, 0, 0, 0, 1),
  (78, 'rapidash', 'Rapidash', 17, 950, 'Very competitive, this POKéMON will chase anything that moves fast in the hopes of racing it.', 4, 65, 100, 70, 80, 80, 105, 0, 0, 0, 0, 0, 2),
  (79, 'slowpoke', 'Slowpoke', 12, 360, 'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.', 4, 90, 65, 65, 40, 40, 15, 1, 0, 0, 0, 0, 0),
  (80, 'slowbro', 'Slowbro', 16, 785, 'The SHELLDER that is latched onto SLOWPOKE’s tail is said to feed on the host’s left over scraps.', 4, 95, 75, 110, 100, 80, 30, 0, 0, 2, 0, 0, 0),
  (81, 'magnemite', 'Magnemite', 3, 60, 'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.', -1, 25, 35, 70, 95, 55, 45, 0, 0, 0, 1, 0, 0),
  (82, 'magneton', 'Magneton', 10, 600, 'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.', -1, 50, 60, 95, 120, 70, 70, 0, 0, 0, 2, 0, 0),
  (83, 'farfetchd', 'Farfetch''d', 8, 150, 'The sprig of green onions it holds is its weapon. It is used much like a metal sword.', 4, 52, 90, 55, 58, 62, 60, 0, 1, 0, 0, 0, 0),
  (84, 'doduo', 'Doduo', 14, 392, 'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.', 4, 35, 85, 45, 35, 35, 75, 0, 1, 0, 0, 0, 0),
  (85, 'dodrio', 'Dodrio', 18, 852, 'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.', 4, 60, 110, 70, 60, 60, 110, 0, 2, 0, 0, 0, 0),
  (86, 'seel', 'Seel', 11, 900, 'The protruding horn on its head is very hard. It is used for bashing through thick ice.', 4, 65, 45, 55, 45, 70, 45, 0, 0, 0, 0, 1, 0),
  (87, 'dewgong', 'Dewgong', 17, 1200, 'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.', 4, 90, 70, 80, 70, 95, 70, 0, 0, 0, 0, 2, 0),
  (88, 'grimer', 'Grimer', 9, 300, 'Appears in filthy areas. Thrives by sucking up polluted sludge that is pumped out of factories.', 4, 80, 80, 50, 40, 50, 25, 1, 0, 0, 0, 0, 0),
  (89, 'muk', 'Muk', 12, 300, 'Thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.', 4, 105, 105, 75, 65, 100, 50, 1, 1, 0, 0, 0, 0),
  (90, 'shellder', 'Shellder', 3, 40, 'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.', 4, 30, 65, 100, 45, 25, 40, 0, 0, 1, 0, 0, 0),
  (91, 'cloyster', 'Cloyster', 15, 1325, 'When attacked, it launches its horns in quick volleys. Its innards have never been seen.', 4, 50, 95, 180, 85, 45, 70, 0, 0, 2, 0, 0, 0),
  (92, 'gastly', 'Gastly', 13, 1, 'Almost invisible, this gaseous POKéMON cloaks the target and puts it to sleep without notice.', 4, 30, 35, 30, 100, 35, 80, 0, 0, 0, 1, 0, 0),
  (93, 'haunter', 'Haunter', 16, 1, 'Because of its ability to slip through block walls, it is said to be from another dimension.', 4, 45, 50, 45, 115, 55, 95, 0, 0, 0, 2, 0, 0),
  (94, 'gengar', 'Gengar', 15, 405, 'Under a full moon, this POKéMON likes to mimic the shadows of people and laugh at their fright.', 4, 60, 65, 60, 130, 75, 110, 0, 0, 0, 3, 0, 0),
  (95, 'onix', 'Onix', 88, 2100, 'As it grows, the stone portions of its body harden to become similar to a diamond, but colored black.', 4, 35, 45, 160, 30, 45, 70, 0, 0, 1, 0, 0, 0),
  (96, 'drowzee', 'Drowzee', 10, 324, 'Puts enemies to sleep then eats their dreams. Occasionally gets sick from eating bad dreams.', 4, 60, 48, 45, 43, 90, 42, 0, 0, 0, 0, 1, 0),
  (97, 'hypno', 'Hypno', 16, 756, 'When it locks eyes with an enemy, it will use a mix of PSI moves such as HYPNOSIS and CONFUSION.', 4, 85, 73, 70, 73, 115, 67, 0, 0, 0, 0, 2, 0),
  (98, 'krabby', 'Krabby', 4, 65, 'Its pincers are not only powerful weapons, they are used for balance when walking sideways.', 4, 30, 105, 90, 25, 25, 50, 0, 1, 0, 0, 0, 0),
  (99, 'kingler', 'Kingler', 13, 600, 'The large pincer has 10000 hp of crushing power. However, its huge size makes it unwieldy to use.', 4, 55, 130, 115, 50, 50, 75, 0, 2, 0, 0, 0, 0),
  (100, 'voltorb', 'Voltorb', 5, 104, 'Usually found in power plants. Easily mistaken for a POKé BALL, they have zapped many people.', -1, 40, 30, 50, 55, 55, 100, 0, 0, 0, 0, 0, 1),
  (101, 'electrode', 'Electrode', 12, 666, 'It stores electric energy under very high pressure. It often explodes with little or no provocation.', -1, 60, 50, 70, 80, 80, 150, 0, 0, 0, 0, 0, 2),
  (102, 'exeggcute', 'Exeggcute', 4, 25, 'Often mistaken for eggs. When disturbed, they quickly gather and attack in swarms.', 4, 60, 40, 80, 60, 45, 40, 0, 0, 1, 0, 0, 0),
  (103, 'exeggutor', 'Exeggutor', 20, 1200, 'Legend has it that on rare occasions, one of its heads will drop off and continue on as an EXEGGCUTE.', 4, 95, 95, 85, 125, 75, 55, 0, 0, 0, 2, 0, 0),
  (104, 'cubone', 'Cubone', 4, 65, 'Because it never removes its skull helmet, no one has ever seen this POKéMON’s real face.', 4, 50, 50, 95, 40, 50, 35, 0, 0, 1, 0, 0, 0),
  (105, 'marowak', 'Marowak', 10, 450, 'The bone it holds is its key weapon. It throws the bone skillfully like a boomerang to KO targets.', 4, 60, 80, 110, 50, 80, 45, 0, 0, 2, 0, 0, 0),
  (106, 'hitmonlee', 'Hitmonlee', 15, 498, 'When in a hurry, its legs lengthen progressively. It runs smoothly with extra long, loping strides.', 0, 50, 120, 53, 35, 110, 87, 0, 2, 0, 0, 0, 0),
  (107, 'hitmonchan', 'Hitmonchan', 14, 502, 'While apparently doing nothing, it fires punches in lightning fast volleys that are impossible to see.', 0, 50, 105, 79, 35, 110, 76, 0, 0, 0, 0, 2, 0),
  (108, 'lickitung', 'Lickitung', 12, 655, 'Its tongue can be extended like a chameleon’s. It leaves a tingling sensation when it licks enemies.', 4, 90, 55, 75, 60, 75, 30, 2, 0, 0, 0, 0, 0),
  (109, 'koffing', 'Koffing', 6, 10, 'Because it stores several kinds of toxic gases in its body, it is prone to exploding without warning.', 4, 40, 65, 95, 60, 45, 35, 0, 0, 1, 0, 0, 0),
  (110, 'weezing', 'Weezing', 12, 95, 'Where two kinds of poison gases meet, 2 KOFFINGs can fuse into a WEEZING over many years.', 4, 65, 90, 120, 85, 70, 60, 0, 0, 2, 0, 0, 0),
  (111, 'rhyhorn', 'Rhyhorn', 10, 1150, 'Its massive bones are 1000 times harder than human bones. It can easily knock a trailer flying.', 4, 80, 85, 95, 30, 30, 25, 0, 0, 1, 0, 0, 0),
  (112, 'rhydon', 'Rhydon', 19, 1200, 'Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees.', 4, 105, 130, 120, 45, 45, 40, 0, 2, 0, 0, 0, 0),
  (113, 'chansey', 'Chansey', 11, 346, 'A rare and elusive POKéMON that is said to bring happiness to those who manage to get it.', 8, 250, 5, 5, 35, 105, 50, 2, 0, 0, 0, 0, 0),
  (114, 'tangela', 'Tangela', 10, 350, 'The whole body is swathed with wide vines that are similar to seaweed. Its vines shake as it walks.', 4, 65, 55, 115, 100, 40, 60, 0, 0, 1, 0, 0, 0),
  (115, 'kangaskhan', 'Kangaskhan', 22, 800, 'The infant rarely ventures out of its mother’s protective pouch until it is 3 years old.', 8, 105, 95, 80, 40, 80, 90, 2, 0, 0, 0, 0, 0),
  (116, 'horsea', 'Horsea', 4, 80, 'Known to shoot down flying bugs with precision blasts of ink from the surface of the water.', 4, 30, 40, 70, 70, 25, 60, 0, 0, 0, 1, 0, 0),
  (117, 'seadra', 'Seadra', 12, 250, 'Capable of swimming backwards by rapidly flapping its wing-like pectoral fins and stout tail.', 4, 55, 65, 95, 95, 45, 85, 0, 0, 1, 1, 0, 0),
  (118, 'goldeen', 'Goldeen', 6, 150, 'Its tail fin billows like an elegant ballroom dress, giving it the nickname of the Water Queen.', 4, 45, 67, 60, 35, 50, 63, 0, 1, 0, 0, 0, 0),
  (119, 'seaking', 'Seaking', 13, 390, 'In the autumn spawning season, they can be seen swimming powerfully up rivers and creeks.', 4, 80, 92, 65, 65, 80, 68, 0, 2, 0, 0, 0, 0),
  (120, 'staryu', 'Staryu', 8, 345, 'An enigmatic POKéMON that can effortlessly regenerate any appendage it loses in battle.', -1, 30, 45, 55, 70, 55, 85, 0, 0, 0, 0, 0, 1),
  (121, 'starmie', 'Starmie', 11, 800, 'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.', -1, 60, 75, 85, 100, 85, 115, 0, 0, 0, 0, 0, 2),
  (122, 'mr-mime', 'Mr. Mime', 13, 545, 'If interrupted while it is miming, it will slap around the offender with its broad hands.', 4, 40, 45, 65, 100, 120, 90, 0, 0, 0, 0, 2, 0),
  (123, 'scyther', 'Scyther', 15, 560, 'With ninja-like agility and speed, it can create the illusion that there is more than one.', 4, 70, 110, 80, 55, 80, 105, 0, 1, 0, 0, 0, 0),
  (124, 'jynx', 'Jynx', 14, 406, 'It seductively wiggles its hips as it walks. It can cause people to dance in unison with it.', 8, 65, 50, 35, 115, 95, 95, 0, 0, 0, 2, 0, 0),
  (125, 'electabuzz', 'Electabuzz', 11, 300, 'Normally found near power plants, they can wander away and cause major blackouts in cities.', 2, 65, 83, 57, 95, 85, 105, 0, 0, 0, 0, 0, 2),
  (126, 'magmar', 'Magmar', 13, 445, 'Its body always burns with an orange glow that enables it to hide perfectly among flames.', 2, 65, 95, 57, 100, 85, 93, 0, 0, 0, 2, 0, 0),
  (127, 'pinsir', 'Pinsir', 15, 550, 'If it fails to crush the victim in its pincers, it will swing it around and toss it hard.', 4, 65, 125, 100, 55, 70, 85, 0, 2, 0, 0, 0, 0),
  (128, 'tauros', 'Tauros', 14, 884, 'When it targets an enemy, it charges furiously while whipping its body with its long tails.', 0, 75, 100, 95, 40, 70, 110, 0, 1, 0, 0, 0, 1),
  (129, 'magikarp', 'Magikarp', 9, 100, 'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.', 4, 20, 10, 55, 15, 20, 80, 0, 0, 0, 0, 0, 1),
  (130, 'gyarados', 'Gyarados', 65, 2350, 'Rarely seen in the wild. Huge and vicious, it is capable of destroying entire cities in a rage.', 4, 95, 125, 79, 60, 100, 81, 0, 2, 0, 0, 0, 0),
  (131, 'lapras', 'Lapras', 25, 2200, 'A POKéMON that has been overhunted almost to extinction. It can ferry people across the water.', 4, 130, 85, 80, 85, 95, 60, 2, 0, 0, 0, 0, 0),
  (132, 'ditto', 'Ditto', 3, 40, 'Capable of copying an enemy’s genetic code to instantly transform itself into a duplicate of the enemy.', -1, 48, 48, 48, 48, 48, 48, 1, 0, 0, 0, 0, 0),
  (133, 'eevee', 'Eevee', 3, 65, 'Its genetic code is irregular. It may mutate if it is exposed to radiation from element STONEs.', 1, 55, 55, 50, 45, 65, 55, 0, 0, 0, 0, 1, 0),
  (134, 'vaporeon', 'Vaporeon', 10, 290, 'Lives close to water. Its long tail is ridged with a fin which is often mistaken for a mermaid’s.', 1, 130, 65, 60, 110, 95, 65, 2, 0, 0, 0, 0, 0),
  (135, 'jolteon', 'Jolteon', 8, 245, 'It accumulates negative ions in the atmosphere to blast out 10000-volt lightning bolts.', 1, 65, 65, 60, 110, 95, 130, 0, 0, 0, 0, 0, 2),
  (136, 'flareon', 'Flareon', 9, 250, 'When storing thermal energy in its body, its temperature could soar to over 1600 degrees.', 1, 65, 130, 60, 95, 110, 65, 0, 2, 0, 0, 0, 0),
  (137, 'porygon', 'Porygon', 8, 365, 'A POKéMON that consists entirely of programming code. Capable of moving freely in cyberspace.', -1, 65, 60, 70, 85, 75, 40, 0, 0, 0, 1, 0, 0),
  (138, 'omanyte', 'Omanyte', 4, 75, 'Although long extinct, in rare cases, it can be genetically resurrected from fossils.', 1, 35, 40, 100, 90, 55, 35, 0, 0, 1, 0, 0, 0),
  (139, 'omastar', 'Omastar', 10, 350, 'A prehistoric POKéMON that died out when its heavy shell made it impossible to catch prey.', 1, 70, 60, 125, 115, 70, 55, 0, 0, 2, 0, 0, 0),
  (140, 'kabuto', 'Kabuto', 5, 115, 'A POKéMON that was resurrected from a fossil found in what was once the ocean floor eons ago.', 1, 30, 80, 90, 55, 45, 55, 0, 0, 1, 0, 0, 0),
  (141, 'kabutops', 'Kabutops', 13, 405, 'Its sleek shape is perfect for swimming. It slashes prey with its claws and drains the body fluids.', 1, 60, 115, 105, 65, 70, 80, 0, 2, 0, 0, 0, 0),
  (142, 'aerodactyl', 'Aerodactyl', 18, 590, 'A ferocious, prehistoric POKéMON that goes for the enemy’s throat with its serrated saw-like fangs.', 1, 80, 105, 65, 60, 75, 130, 0, 0, 0, 0, 0, 2),
  (143, 'snorlax', 'Snorlax', 21, 4600, 'Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.', 1, 160, 110, 65, 65, 110, 30, 2, 0, 0, 0, 0, 0),
  (144, 'articuno', 'Articuno', 17, 554, 'A legendary bird POKéMON that is said to appear to doomed people who are lost in icy mountains.', -1, 90, 85, 100, 95, 125, 85, 0, 0, 0, 0, 3, 0),
  (145, 'zapdos', 'Zapdos', 16, 526, 'A legendary bird POKéMON that is said to appear from clouds while dropping enormous lightning bolts.', -1, 90, 90, 85, 125, 90, 100, 0, 0, 0, 3, 0, 0),
  (146, 'moltres', 'Moltres', 20, 600, 'Known as the legendary bird of fire. Every flap of its wings creates a dazzling flash of flames.', -1, 90, 100, 90, 125, 85, 90, 0, 0, 0, 3, 0, 0),
  (147, 'dratini', 'Dratini', 18, 33, 'Long considered a mythical POKéMON until recently when a small colony was found living underwater.', 4, 41, 64, 45, 50, 50, 50, 0, 1, 0, 0, 0, 0),
  (148, 'dragonair', 'Dragonair', 40, 165, 'A mystical POKéMON that exudes a gentle aura. Has the ability to change climate conditions.', 4, 61, 84, 65, 70, 70, 70, 0, 2, 0, 0, 0, 0),
  (149, 'dragonite', 'Dragonite', 22, 2100, 'An extremely rarely seen marine POKéMON. Its intelligence is said to match that of humans.', 4, 91, 134, 95, 100, 100, 80, 0, 3, 0, 0, 0, 0),
  (150, 'mewtwo', 'Mewtwo', 20, 1220, 'It was created by a scientist after years of horrific gene splicing and DNA engineering experiments.', -1, 106, 110, 90, 154, 90, 130, 0, 0, 0, 3, 0, 0),
  (151, 'mew', 'Mew', 4, 40, 'So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.', -1, 100, 100, 100, 100, 100, 100, 3, 0, 0, 0, 0, 0)
