  (1, '10000000-volt-thunderbolt', '10,000,000 Volt Thunderbolt', 4, 'special', 195, null, 1, 0, 'Pikachu-exclusive Z-Move. High critical hit ratio.', 10000, 'ranged', 'enemy', 'single', 4, 0, 0, 0, 0, 0, 0, 'Targets a single adjacent Pokémon.'),
  (2, 'absorb', 'Absorb', 5, 'special', 20, 100, 25, 0, 'User recovers half the HP inflicted on opponent.', 1750, 'ranged', 'enemy', 'single', 4, 0, 0, 0, 50, 0, 0, 'Targets a single adjacent Pokémon.'),
  (3, 'accelerock', 'Accelerock', 13, 'physical', 40, 100, 20, 1, 'User attacks first.', 2000, 'melee', 'enemy', 'single', 1, 0, 0, 0, 0, 0, 0, 'Targets a single adjacent Pokémon.'),
  (4, 'acid', 'Acid', 8, 'special', 40, 100, 30, 0, 'May lower opponent''s Special Defense.', 2000, 'ranged', 'all_enemies', 'square', 4, 1, 0, 0, 0, 0, 0, 'Targets all adjacent foes.'),
  (5, 'acid-armor', 'Acid Armor', 8, 'status', null, null, 20, 0, 'Sharply raises user''s Defense.', 8000, 'melee', 'self', 'single', 0, 0, 0, 0, 0, 0, 0, 'Targets the user.'),
