  (7, 'acid-spray', 'Acid Spray', 8, 'special', 40, 100, 20, 0, 'Sharply lowers opponent''s Special Defense.', 2000, 'ranged', 'enemy', 'single', 4, 0, 0, 0, 0, 0, 0, 'Targets a single adjacent Pokémon.'),
  (8, 'acrobatics', 'Acrobatics', 10, 'physical', 55, 100, 15, 0, 'Stronger when the user does not have a held item.', 2825, 'melee', 'enemy', 'single', 1, 0, 0, 0, 0, 0, 0, 'Targets any single Pokémon on the field including non-adjacent ones.'),
